import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.DTisvaUJ.js";const u=JSON.parse('{"title":"음성 인식 엔진 비교","description":"Mutelink의 Whisper·Parakeet·Haas·Qwen3-ASR 지원 언어, 다운로드 크기와 선택 방법을 비교합니다.","frontmatter":{"description":"Mutelink의 Whisper·Parakeet·Haas·Qwen3-ASR 지원 언어, 다운로드 크기와 선택 방법을 비교합니다.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/speech-recognition"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:title","content":"음성 인식 엔진 비교 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink의 Whisper·Parakeet·Haas·Qwen3-ASR 지원 언어, 다운로드 크기와 선택 방법을 비교합니다."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/ko/compare/speech-recognition"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"음성 인식 엔진 비교 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink의 Whisper·Parakeet·Haas·Qwen3-ASR 지원 언어, 다운로드 크기와 선택 방법을 비교합니다."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/compare/speech-recognition"}]]},"headers":[],"relativePath":"ko/compare/speech-recognition.md","filePath":"ko/compare/speech-recognition.md"}'),n={name:"ko/compare/speech-recognition.md"};function i(o,t,l,h,s,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="音声認識エンジンの比較" tabindex="-1">음성 인식 엔진 비교 <a class="header-anchor" href="#音声認識エンジンの比較" aria-label="Permalink to &quot;음성 인식 엔진 비교 {#音声認識エンジンの比較}&quot;">​</a></h1><p>말하는 언어별로 인식 엔진을 선택할 수 있습니다. 상대를 인식하는 들리는 음성에도 같은 로컬 엔진을 씁니다.</p><h2 id="迷ったら" tabindex="-1">고르기 어렵다면 <a class="header-anchor" href="#迷ったら" aria-label="Permalink to &quot;고르기 어렵다면 {#迷ったら}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>말하는 언어</th><th>권장</th></tr></thead><tbody><tr><td>일본어</td><td>Parakeet 일본어 TDT 또는 Haas-ja</td></tr><tr><td>영어</td><td>Parakeet 영어</td></tr><tr><td>다른 언어 또는 자동 언어 감지</td><td>Qwen3-ASR 또는 Whisper turbo</td></tr><tr><td>PC 성능이 낮을 때</td><td>Web Speech(클라우드)</td></tr></tbody></table><h2 id="エンジンの一覧" tabindex="-1">엔진 목록 <a class="header-anchor" href="#エンジンの一覧" aria-label="Permalink to &quot;엔진 목록 {#エンジンの一覧}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>엔진</th><th>실행 위치</th><th>언어</th><th>다운로드</th><th>발화 길이 대비 시간</th><th>특징</th></tr></thead><tbody><tr><td>Parakeet 일본어 TDT</td><td>이 PC</td><td>일본어</td><td>약 1.0GB</td><td>약 3.5%</td><td>빠르고 정확하며 문장 부호 포함</td></tr><tr><td>Haas-ja</td><td>이 PC</td><td>일본어</td><td>약 480MB</td><td>약 13%</td><td>일반 대화에서 Parakeet 일본어 TDT보다 약간 정확하며 한자·문장 부호도 직접 생성</td></tr><tr><td>Parakeet 영어</td><td>이 PC</td><td>영어 및 유럽 언어</td><td>약 670MB</td><td>약 5%</td><td>빠르며 문장 부호·대문자 포함. 일본어·중국어·한국어 미지원</td></tr><tr><td>Qwen3-ASR</td><td>이 PC</td><td>일본어·영어·중국어·한국어 등 52개 언어</td><td>약 1.0GB</td><td>약 10~20%</td><td>하나의 모델로 다국어와 자동 언어 감지</td></tr><tr><td>Whisper turbo</td><td>이 PC</td><td>일본어·영어·중국어·한국어 등</td><td>약 1.0GB</td><td>약 30%</td><td>자동 언어 감지, 다른 로컬 엔진보다 느림</td></tr><tr><td>Web Speech(Microsoft)</td><td>클라우드</td><td>다국어</td><td>없음</td><td>—</td><td>모델 다운로드 불필요, 인터넷 필요, 음성을 Microsoft로 전송</td></tr><tr><td>Google(비공식·실험적)</td><td>클라우드</td><td>다국어</td><td>없음</td><td>—</td><td>공식 API가 아니므로 예고 없이 중단될 수 있음. 음성을 Google로 전송</td></tr></tbody></table><ul><li>로컬 엔진은 GPU 없이 CPU만 쓰며 음성은 PC 밖으로 나가지 않습니다.</li><li>속도는 개발자 PC(Ryzen 7 7700)의 참고값입니다. 약 5%라면 10초 발화를 약 0.5초에 인식한다는 뜻입니다.</li><li>Haas-ja의 약 13%는 기존 상대 측정(Parakeet 일본어 TDT의 약 3.6배)을 약 3.5% 기준으로 환산해 반올림한 값입니다.</li><li>언어를 자동으로 설정할 수 있는 것은 Qwen3-ASR와 Whisper turbo뿐입니다.</li></ul><h2 id="合成音声を聞かせた結果" tabindex="-1">합성 음성 인식 결과 <a class="header-anchor" href="#合成音声を聞かせた結果" aria-label="Permalink to &quot;합성 음성 인식 결과 {#合成音声を聞かせた結果}&quot;">​</a></h2><p>Qwen3-TTS·Irodori-TTS의 같은 음성을 각 엔진에 들려주고 원문과 비교했습니다. <strong>엔진별 경향 차이</strong>를 보는 참고 자료입니다.</p><p>각 칸은 “평균 오류율 · 완전 일치 문장/30”입니다. 오류율은 낮을수록 정확합니다.</p><h3 id="日本語-読みで比べたもの" tabindex="-1">일본어(읽기 기준 비교) <a class="header-anchor" href="#日本語-読みで比べたもの" aria-label="Permalink to &quot;일본어(읽기 기준 비교) {#日本語-読みで比べたもの}&quot;">​</a></h3><p>Parakeet 일본어 TDT는 앱이 나중에 한자를 보정하므로 여기서는 양쪽을 히라가나로 바꾸어 비교합니다.</p><table tabindex="0"><thead><tr><th>들려준 음성</th><th>Whisper turbo</th><th>Qwen3-ASR</th><th>Parakeet 일본어 TDT</th><th>Haas-ja</th></tr></thead><tbody><tr><td>Irodori-TTS</td><td>5.6% · 25/30</td><td>13.8% · 21/30</td><td>6.9% · 20/30</td><td>4.5% · 25/30</td></tr><tr><td>Qwen3-TTS</td><td>14.9% · 23/30</td><td>17.3% · 19/30</td><td>11.1% · 23/30</td><td>9.7% · 23/30</td></tr></tbody></table><h3 id="ほかの言語-qwen3-ttsの音声" tabindex="-1">다른 언어(Qwen3-TTS 음성) <a class="header-anchor" href="#ほかの言語-qwen3-ttsの音声" aria-label="Permalink to &quot;다른 언어(Qwen3-TTS 음성) {#ほかの言語-qwen3-ttsの音声}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>언어</th><th>Whisper turbo</th><th>Qwen3-ASR</th><th>Parakeet 영어</th></tr></thead><tbody><tr><td>영어</td><td>2.1% · 27/30</td><td>0.8% · 28/30</td><td>2.9% · 25/30</td></tr><tr><td>중국어</td><td>5.4% · 25/30</td><td>0.3% · 29/30</td><td>미지원</td></tr><tr><td>한국어</td><td>2.4% · 27/30</td><td>4.0% · 24/30</td><td>미지원</td></tr><tr><td>독일어</td><td>3.9% · 26/30</td><td>4.4% · 25/30</td><td>4.7% · 23/30</td></tr><tr><td>스페인어</td><td>4.2% · 27/30</td><td>2.8% · 28/30</td><td>3.9% · 25/30</td></tr><tr><td>프랑스어</td><td>6.6% · 24/30</td><td>6.1% · 27/30</td><td>2.5% · 26/30</td></tr><tr><td>이탈리아어</td><td>6.4% · 24/30</td><td>11.2% · 21/30</td><td>5.9% · 21/30</td></tr><tr><td>포르투갈어</td><td>6.2% · 26/30</td><td>7.4% · 24/30</td><td>6.5% · 21/30</td></tr><tr><td>러시아어</td><td>2.6% · 26/30</td><td>9.3% · 22/30</td><td>4.4% · 25/30</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">결과의 한계</p><ul><li>사람의 마이크 음성이 아닌 합성 음성 결과입니다. 실제 음성·잡음·말투에 따라 결과가 달라집니다.</li><li>언어별 일상 짧은 문장 30개이며 AI가 작성했고 원어민 검수는 없습니다.</li><li>일본어·중국어·한국어는 글자 단위, 나머지는 단어 단위로 계산하며 “3”과 “三” 같은 숫자 표기나 바꿔 말하기도 오류로 셉니다.</li><li>앱의 한자 변환·문장 부호 보정 등 후처리는 적용하지 않았습니다.</li><li>클라우드 엔진(Web Speech·Google)은 검사하지 않았습니다.</li></ul></div>',16)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
